<?php
namespace App\Services;
use App\Models\InventoryItem;use App\Models\Order;use App\Models\ProductVariant;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class CheckoutService {public function place(array $data,array $cart,?int $userId,?string $ip):Order {if(!$cart)throw ValidationException::withMessages(['cart'=>'Your bag is empty.']);return DB::transaction(function()use($data,$cart,$userId,$ip){$subtotal=0;$verified=[];foreach($cart as $line){$variant=ProductVariant::with('product')->lockForUpdate()->findOrFail($line['variant_id']);if(!$variant->is_active||$variant->product->status!=='active')throw ValidationException::withMessages(['cart'=>"{$line['name']} is unavailable."]);$qty=(float)$line['quantity'];$stock=InventoryItem::where('product_variant_id',$variant->id)->lockForUpdate()->orderByDesc('quantity_on_hand')->first();if($variant->track_inventory&&$stock&&((float)$stock->quantity_on_hand-(float)$stock->quantity_reserved)<$qty)throw ValidationException::withMessages(['cart'=>"Not enough stock for {$variant->product->name}."]);if($stock)$stock->increment('quantity_reserved',$qty);$price=(float)$variant->price;$subtotal+=$price*$qty;$verified[]=compact('variant','qty','price');}$shipping=$data['shipping_method']==='international'?0:($data['city']==='Dhaka'?80:130);$order=Order::create(array_merge($data,['uuid'=>(string)Str::uuid(),'number'=>$this->nextNumber(),'user_id'=>$userId,'status'=>'pending_payment','payment_status'=>'unpaid','currency'=>'BDT','subtotal'=>$subtotal,'shipping_total'=>$shipping,'grand_total'=>$subtotal+$shipping,'payment_method'=>'pending_selection','client_ip'=>$ip]));foreach($verified as $line){$v=$line['variant'];$order->items()->create(['product_id'=>$v->product_id,'product_variant_id'=>$v->id,'product_name'=>$v->product->name,'variant_name'=>$v->name,'sku'=>$v->sku,'quantity'=>$line['qty'],'unit_price'=>$line['price'],'line_total'=>$line['qty']*$line['price'],'snapshot'=>['slug'=>$v->product->slug]]);}return $order->fresh('items');},3);}private function nextNumber():string{$prefix='AMER-'.now()->format('ymd').'-';$last=Order::where('number','like',$prefix.'%')->lockForUpdate()->max('number');return $prefix.str_pad((string)(((int)substr((string)$last,-4))+1),4,'0',STR_PAD_LEFT);}}
